<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router'
import { NButton, NCheckbox, NInput, NInputNumber, NSelect } from 'naive-ui'
import { agentApi, listAgentSources, type AgentDetail, type CapabilityCatalog, type Revision, type Validation, type Operation, type Agent } from '../agents/api'
import { modelApi, memberError, type ParseResult } from '../model-management/api'
import { client } from '../../shared/api/client'
import { environment, loadEnvironment } from '../../shared/environment'
import type { Source } from '../../shared/api/types'
import ErrorBanner from '../../shared/ui/ErrorBanner.vue'
import EmptyState from '../../shared/ui/EmptyState.vue'
import MediaPlayer from '../../shared/media/MediaPlayer.vue'
import RegionEditor from '../../shared/media/RegionEditor.vue'
import { newGroup, bindings, selectSources, copyForNewTask, draftIssue, retryKey, type Config, type Channel } from './state'
import './task-create.css'
const route=useRoute(),router=useRouter(),step=ref(0),name=ref(''),description=ref(''),config=ref<Config>({schema_version:'1.0',channels:[newGroup()]})
const sources=ref<Source[]>([]),catalog=ref<CapabilityCatalog|null>(null),agents=ref<Agent[]>([]),busy=ref(false),loading=ref(true),error=ref(''),catalogError=ref(''),sourceError=ref(''),notice=ref(''),loadError=ref('')
const agent=ref<AgentDetail|null>(null),revision=ref<Revision|null>(null),validation=ref<Validation|null>(null),operation=ref<Operation|null>(null),confirmed=ref(false),reviewed=ref(false),selectedGroup=ref(0),activeSource=ref(''),copyId=ref<string|null>(null)
const parsedText=reactive<Record<string,string>>({})
const parsed=reactive<Record<string,ParseResult>>({}),pending=reactive<Record<string,boolean>>({}),saved=ref(''),evaluated=ref('')
const signature=computed(()=>JSON.stringify({name:name.value,description:description.value,config:config.value})),dirty=computed(()=>signature.value!==saved.value),current=computed(()=>config.value.channels?.[selectedGroup.value]),demo=computed(()=>environment.value?.data_origin==='mock'),hasPending=computed(()=>Object.values(pending).some(Boolean))
const frozen=computed(()=>busy.value||!!operation.value||revision.value?.state==='published'||!!loadError.value)
const sourceOptions=computed(()=>sources.value.map(s=>({label:`${s.name} · ${s.kind==='file'?'录像':'直播'}`,value:s.id})))
const previewSource=computed(()=>sources.value.find(s=>s.id===activeSource.value))
const validEvaluation=computed(()=>validation.value?.verdict==='executable'&&evaluated.value===signature.value&&Date.parse(validation.value.expires_at)>Date.now())
const canStart=computed(()=>validEvaluation.value&&confirmed.value&&!busy.value&&!hasPending.value&&!operation.value)
const blockReason=computed(()=>hasPending.value?'请先保存正在绘制的区域。':!validEvaluation.value?'请先验证当前完整配置为可执行。':!confirmed.value?'请核对最终配置并勾选确认。':'')
const business:Record<string,string>={person:'人员',vehicle:'车辆',intrusion:'进入区域',dwell:'区域停留',absence:'缺员 / 离岗'}
const label=(v:string)=>business[v]??v
const verdictLabel=(v:string)=>({executable:'可执行',clarification_required:'需要补充条件',unsupported:'暂不支持',insufficient_evidence:'证据不足'} as Record<string,string>)[v]??v
const statusLabel=(v:string)=>({pending:'已受理',running:'处理中',succeeded:'启动完成',partial_failed:'部分启动失败',failed:'启动失败',canceled:'已取消'} as Record<string,string>)[v]??v
const refKey=(value:unknown)=>JSON.stringify(value)
function capability(c:Channel){return catalog.value?.items.find(i=>refKey(i.reference)===refKey(c.capability_ref))}
function chooseCapability(c:Channel,key:string|null){c.capability_ref=catalog.value?.items.find(i=>refKey(i.reference)===key)?.reference??null}
function changeSources(c:Channel,ids:string[]){if(ids.length>16){error.value='每个监测组最多选择16路视频。';return}if(bindings(c).filter(b=>!ids.includes(b.source_id)).some(b=>pending[`${c.channel_id}:${b.source_id}`])){error.value='请先完成或撤销被移除视频正在绘制的区域。';return}selectSources(c,ids);if(!ids.includes(activeSource.value))activeSource.value=ids[0]??''}
function removeGroup(index:number){const c=config.value.channels?.[index];if(!c)return;if(bindings(c).some(b=>pending[`${c.channel_id}:${b.source_id}`])){error.value='请先完成或撤销该组正在绘制的区域。';return}config.value.channels?.splice(index,1);selectedGroup.value=Math.max(0,index-1)}
let stopped=false,pollTimer:ReturnType<typeof setTimeout>|undefined,allowLeave=false
watch(signature,()=>{validation.value=null;evaluated.value='';confirmed.value=false;reviewed.value=false})
watch(selectedGroup,()=>{activeSource.value=current.value?bindings(current.value)[0]?.source_id??'':''})
watch(step,()=>{error.value=''})
async function loadCatalog(){try{catalog.value=await agentApi.catalog();catalogError.value=''}catch(e){catalog.value=null;catalogError.value=memberError(e)}}
async function loadSources(){try{sources.value=await listAgentSources();sourceError.value=''}catch(e){sourceError.value=memberError(e)}}
async function loadDraft(){loadError.value='';if(!route.query.draft)return;try{const value=await agentApi.detail(String(route.query.draft));agent.value=value;revision.value=value.latest_revision;name.value=value.name;description.value=value.description;config.value=JSON.parse(JSON.stringify(value.latest_revision.config)) as Config;await Promise.resolve();saved.value=signature.value;if(revision.value?.state==='published'&&revision.value.latest_validation_id){validation.value=await agentApi.validation(revision.value.latest_validation_id);evaluated.value=signature.value;confirmed.value=true}notice.value=value.latest_revision.state==='published'?'配置已发布，请在智能体详情核对运行状态。':'已恢复服务端草稿。'}catch(e){loadError.value=memberError(e)}}
async function recoverCreate(){
  if(route.query.draft)return
  const raw=sessionStorage.getItem('vision.create.new');if(!raw)return
  try{const pendingRequest=JSON.parse(raw) as {signature:string;key:string};const body=JSON.parse(pendingRequest.signature) as {name:string;description:string;config:Config};if(!body.name||!body.config?.channels||!pendingRequest.key)return;name.value=body.name;description.value=body.description;config.value=body.config;agent.value=await agentApi.create(body,pendingRequest.key);revision.value=agent.value.latest_revision;sessionStorage.removeItem('vision.create.new');saved.value=signature.value;await router.replace({path:'/create',query:{draft:agent.value.id}});notice.value='已恢复上次中断的创建请求，未重复创建实例。'}catch(e){error.value=displayError(e)}
}
async function loadAgents(){try{agents.value=(await agentApi.list()).items}catch{/* optional copy source */}}
async function copyTask(){if(!copyId.value)return;if(dirty.value&&name.value&&!window.confirm('替换当前未保存输入？'))return;busy.value=true;try{const value=await agentApi.detail(copyId.value);agent.value=null;revision.value=null;name.value=`${value.name}（副本）`.slice(0,160);description.value=value.description;config.value=copyForNewTask(value.latest_revision.config);saved.value='';await router.replace({path:'/create'});notice.value='已复制为新任务配置，保存后将获得新的实例和首版配置。'}catch(e){error.value=memberError(e)}finally{busy.value=false}}
async function seed(){busy.value=true;error.value='';try{await agentApi.seed();await Promise.all([loadSources(),loadCatalog(),loadAgents()]);notice.value='已加载模拟录像和直播，仅用于演示配置流程。'}catch(e){error.value=memberError(e)}finally{busy.value=false}}
async function parseCurrent(){const c=current.value;if(!c?.requirement_text.trim())return;busy.value=true;error.value='';try{const result=await modelApi.parse(c.requirement_text);if(result.target)c.target=result.target;if(result.rule)c.rule=result.rule;c.duration_seconds=result.duration_seconds;parsed[c.channel_id!]=result;parsedText[c.channel_id!]=c.requirement_text;notice.value='解析建议已填入，请逐项核对；区域需为每个视频单独绘制。'}catch(e){error.value=memberError(e)}finally{busy.value=false}}
async function persist():Promise<Revision>{
  const issue=draftIssue(name.value,config.value,hasPending.value);if(issue)throw new Error(issue)
  if(!agent.value){const body={name:name.value,description:description.value,config:config.value};agent.value=await agentApi.create(body,retryKey('new',body));revision.value=agent.value.latest_revision;sessionStorage.removeItem('vision.create.new')}
  else{const latest=await agentApi.detail(agent.value.id);if(!revision.value)throw Error('草稿状态缺失，请刷新后重试。');if(latest.name!==name.value||latest.description!==description.value){if(latest.row_version!==agent.value.row_version)throw Error('任务信息已被其他页面修改，请刷新并核对。');agent.value=await agentApi.rename(latest.id,{name:name.value,description:description.value,row_version:latest.row_version})}if(JSON.stringify(latest.latest_revision.config)!==JSON.stringify(config.value))revision.value=await agentApi.save(revision.value,config.value);else revision.value=latest.latest_revision;agent.value=await agentApi.detail(agent.value.id)}
  saved.value=signature.value;await router.replace({path:'/create',query:{draft:agent.value.id}});return revision.value!
}
function displayError(e:unknown){return e instanceof Error&&!('response' in e)?e.message:memberError(e)}
async function saveDraft(){if(busy.value)return;busy.value=true;error.value='';try{await persist();notice.value='草稿已保存，可通过当前页面地址继续编辑。'}catch(e){error.value=displayError(e)}finally{busy.value=false}}
async function evaluate(){if(busy.value)return;if(!reviewed.value){error.value='请先核对原始需求与全部结构化条件。';return}busy.value=true;error.value='';try{const r=await persist();const result=await agentApi.validate(r);revision.value=await client.get<Revision>(`/revisions/${encodeURIComponent(r.id)}`).then(r=>r.data);validation.value=result;evaluated.value=signature.value;confirmed.value=false;step.value=3}catch(e){error.value=displayError(e)}finally{busy.value=false}}
async function poll(){if(stopped||!agent.value||!operation.value)return;try{operation.value=await agentApi.operation(agent.value.id,operation.value.id);if(['pending','running'].includes(operation.value.state))pollTimer=setTimeout(()=>void poll(),1000);else if(operation.value.state==='succeeded'){const workspace=await agentApi.workspace(agent.value.id);notice.value=`启动完成，运行 ID：${workspace.runs.filter(r=>r.revision_id===revision.value?.id).map(r=>r.id).join('、')}`;allowLeave=true;await router.push(`/agents/${agent.value.id}/live`)}}catch(e){error.value=memberError(e)}}
async function start(){if(!canStart.value||!agent.value||!revision.value||!validation.value)return;busy.value=true;error.value='';try{if(revision.value.state==='draft')revision.value=await agentApi.confirm(revision.value,validation.value,retryKey(`confirm:${revision.value.id}`,validation.value));const body={revision_id:revision.value.id,channel_ids:(revision.value.config.channels??[]).map(c=>c.channel_id!),expected_active_run_ids:[]};operation.value=await agentApi.submit(agent.value.id,'start',body,retryKey(`start:${agent.value.id}`,body));sessionStorage.setItem(`vision.create.operation.${agent.value.id}`,operation.value.id);notice.value='启动请求已受理，正在查询各视频的操作结果。';void poll()}catch(e){error.value=displayError(e)}finally{busy.value=false}}
async function reset(){if(busy.value)return;if(dirty.value&&!window.confirm('放弃当前未保存输入？'))return;allowLeave=true;sessionStorage.removeItem('vision.create.new');await router.push('/create');window.location.reload()}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(()=>allowLeave||!dirty.value||window.confirm('有未保存输入，确定离开？'))
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);await Promise.all([loadEnvironment(),loadSources(),loadCatalog(),loadAgents()]);await loadDraft();await recoverCreate();if(!route.query.draft)saved.value=signature.value;if(agent.value){const id=sessionStorage.getItem(`vision.create.operation.${agent.value.id}`);if(id)try{operation.value=await agentApi.operation(agent.value.id,id);void poll()}catch{notice.value='未能恢复操作查询，请在智能体详情核对运行状态。'}}loading.value=false})
onBeforeUnmount(()=>{stopped=true;clearTimeout(pollTimer);window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template>
<div class="page-heading"><div><h1>任务创建</h1><p>配置视频与业务条件，核对能力后创建可追溯的监测任务。</p></div><div class="create-actions"><NButton v-if="demo" :disabled="busy" @click="seed">加载模拟素材</NButton><NButton :disabled="busy" @click="reset">新建另一任务</NButton></div></div>
<div v-if="demo" class="notice">演示模式：解析、校验、运行与报警均为模拟，不代表识别效果。先到“模型管理 → 本地大模型”绑定模拟解析器。</div>
<ErrorBanner :error="loadError" @retry="loadDraft"/><ErrorBanner :error="error" :retryable="false"/><p v-if="notice" class="notice" role="status">{{notice}}</p><div v-if="loading" class="loading-line"/>
<nav class="create-steps" aria-label="任务创建步骤"><button v-for="(title,index) in ['视频源与区域','需求与条件','方案与能力','确认与启动']" :key="title" :aria-current="step===index?'step':undefined" :class="{active:step===index}" :disabled="busy||hasPending" @click="step=index"><span>{{index+1}}</span>{{title}}</button></nav>
<div class="create-layout"><section class="panel create-main"><fieldset :disabled="frozen" class="create-fields">
<template v-if="step===0"><h2>选择视频源与分析范围</h2><p class="create-hint">同组共用需求、规则和模型；视频各自设置区域与录像范围。</p>
<div v-if="!agent" class="create-copy"><NSelect v-model:value="copyId" :options="agents.map(a=>({label:a.name,value:a.id}))" placeholder="可选：从已有智能体复制配置" aria-label="从已有智能体复制" :disabled="frozen"/><NButton :disabled="frozen||!copyId" @click="copyTask">复制</NButton></div>
<div class="field"><label>任务名称</label><NInput v-model:value="name" :disabled="frozen" :maxlength="160" aria-label="任务名称" :input-props="{'aria-label':'任务名称'}" placeholder="例如：北门区域停留监测"/></div><div class="field"><label>说明（可选）</label><NInput v-model:value="description" :disabled="frozen" :maxlength="2000" aria-label="任务说明" :input-props="{'aria-label':'任务说明'}"/></div>
<div class="create-groups"><button v-for="(c,index) in config.channels" :key="c.channel_id" :class="{active:index===selectedGroup}" :disabled="hasPending" type="button" @click="selectedGroup=index">{{c.name||`监测组 ${index+1}`}}</button><NButton size="small" :disabled="frozen||hasPending||(config.channels?.length??0)>=16" @click="config.channels?.push(newGroup());selectedGroup=(config.channels?.length??1)-1">＋ 添加组</NButton></div>
<template v-if="current"><div class="field create-group-name"><NInput v-model:value="current.name" :disabled="frozen" aria-label="监测组名称" :input-props="{'aria-label':'监测组名称'}"/><NButton :disabled="frozen" @click="removeGroup(selectedGroup)">移除组</NButton></div><ErrorBanner :error="sourceError" @retry="loadSources"/><div class="field"><label>组内视频源（最多16路，录像和直播可混选）</label><NSelect multiple filterable :value="bindings(current).map(b=>b.source_id)" :options="sourceOptions" :disabled="frozen" aria-label="组内视频源" @update:value="changeSources(current!, $event)"/></div><EmptyState v-if="!sources.length&&!sourceError" title="还没有视频源" description="请先导入录像或登记摄像头。"><RouterLink to="/sources">前往视频源管理</RouterLink></EmptyState>
<section v-for="b in bindings(current)" :key="current.channel_id+':'+b.source_id" class="create-source"><div class="panel-title"><h3>{{sources.find(s=>s.id===b.source_id)?.name??b.source_id}}</h3><NButton size="tiny" @click="activeSource=activeSource===b.source_id?'':b.source_id">{{activeSource===b.source_id?'关闭预览':'预览'}}</NButton></div><p class="create-hint">{{sources.find(s=>s.id===b.source_id)?.width??'未知'}} × {{sources.find(s=>s.id===b.source_id)?.height??'未知'}} · {{sources.find(s=>s.id===b.source_id)?.fps??'未知'}} fps · {{sources.find(s=>s.id===b.source_id)?.duration_ms!=null?`${sources.find(s=>s.id===b.source_id)!.duration_ms!/1000} 秒`:'直播或时长未知'}}</p>
<template v-if="activeSource===b.source_id&&previewSource"><div v-if="demo" class="create-mock">模拟视频素材 · 仅用于配置练习</div><MediaPlayer v-else :key="b.source_id" :source="previewSource"/></template>
<div v-if="sources.find(s=>s.id===b.source_id)?.kind==='file'" class="field-grid"><div class="field"><label>录像开始位置（秒）</label><NInputNumber :value="b.start_media_ms==null?null:b.start_media_ms/1000" :disabled="frozen" :min="0" :precision="3" aria-label="录像开始秒" :input-props="{'aria-label':'录像开始秒'}" @update:value="b.start_media_ms=$event==null?null:Math.round($event*1000)"/></div><div class="field"><label>录像结束位置（秒）</label><NInputNumber :value="b.end_media_ms==null?null:b.end_media_ms/1000" :disabled="frozen" :min="0" :precision="3" aria-label="录像结束秒" :input-props="{'aria-label':'录像结束秒'}" @update:value="b.end_media_ms=$event==null?null:Math.round($event*1000)"/></div></div>
<RegionEditor :key="current.channel_id+':'+b.source_id" :source="sources.find(s=>s.id===b.source_id)" :regions="b.regions??[]" :demo="demo" :disabled="frozen" @change="b.regions=$event" @pending="pending[`${current!.channel_id}:${b.source_id}`]=$event"/>
</section></template></template>
<template v-else-if="step===1"><h2>描述需求并补充条件</h2><div class="field"><label>当前监测组</label><NSelect v-model:value="selectedGroup" :options="config.channels?.map((c,i)=>({label:c.name,value:i}))??[]" :disabled="frozen" aria-label="选择监测组"/></div><template v-if="current"><div class="field"><label>自然语言监测需求</label><NInput v-model:value="current.requirement_text" :disabled="frozen" type="textarea" :maxlength="8000" :autosize="{minRows:4}" aria-label="监测需求" :input-props="{'aria-label':'监测需求'}" placeholder="有人在区域内停留超过30秒时报警"/></div><NButton :disabled="frozen||!current.requirement_text.trim()" @click="parseCurrent">解析当前组需求</NButton><p class="create-hint">服务未接入时可以手工填写并保存草稿；可执行性仍须服务端验证。</p><div class="field-grid"><div class="field"><label>监测目标</label><NInput v-model:value="current.target" :disabled="frozen" aria-label="监测目标" :input-props="{'aria-label':'监测目标'}" placeholder="例如 person"/></div><div class="field"><label>触发规则</label><NInput v-model:value="current.rule" :disabled="frozen" aria-label="触发规则" :input-props="{'aria-label':'触发规则'}" placeholder="例如 dwell"/></div></div><div class="field"><label>持续时长（秒，不从“太久”自动推断）</label><NInputNumber v-model:value="current.duration_seconds" :disabled="frozen" :min="1" :max="86400" :precision="0" aria-label="持续时长" :input-props="{'aria-label':'持续时长'}"/></div><div v-if="parsed[current.channel_id!]&&parsedText[current.channel_id!]===current.requirement_text" class="create-assessment"><strong>解析建议与待确认项</strong><p>解析器：{{parsed[current.channel_id!].deployment_id}} · {{parsed[current.channel_id!].deployment_version}}</p><ul><li v-for="v in [...parsed[current.channel_id!].missing_conditions,...parsed[current.channel_id!].limitations]" :key="v">{{v}}</li></ul></div></template><EmptyState v-else title="请先添加监测组"/></template>
<template v-else-if="step===2"><h2>匹配模型与模板能力</h2><ErrorBanner :error="catalogError" @retry="loadCatalog"/><EmptyState v-if="catalog&&!catalog.items.length" title="没有经过校验的可用能力" description="可以保存草稿。算法服务未接入时，导入模型仍须等待校验。"><RouterLink to="/models">前往模型管理</RouterLink></EmptyState><section v-for="c in config.channels" :key="c.channel_id" class="create-source"><h3>{{c.name}}</h3><p class="create-hint">原始需求：{{c.requirement_text||'尚未填写'}}</p><div class="field"><label>模型 / 模板与版本</label><NSelect :value="c.capability_ref?refKey(c.capability_ref):null" :disabled="frozen||!!catalogError" :options="catalog?.items.map(i=>({label:`${i.name} · ${i.reference.model_version} / ${i.reference.template_version}`,value:refKey(i.reference)}))??[]" clearable aria-label="模型与模板" @update:value="chooseCapability(c,$event)"/></div><template v-if="capability(c)"><div class="field-grid"><div class="field"><label>确认监测目标</label><NSelect v-model:value="c.target" :disabled="frozen" :options="capability(c)!.targets.map(value=>({label:label(value),value}))" aria-label="能力目标"/></div><div class="field"><label>确认触发规则</label><NSelect v-model:value="c.rule" :disabled="frozen" :options="capability(c)!.rules.map(value=>({label:label(value),value}))" aria-label="能力规则"/></div></div><p class="create-hint">需区域：{{capability(c)!.requires_region?.map(label).join('、')||'未声明'}} · 需时长：{{capability(c)!.requires_duration?.map(label).join('、')||'未声明'}}</p><ul><li v-for="v in capability(c)!.limitations" :key="v">{{v}}</li></ul></template><p v-else-if="c.capability_ref" class="notice">原模型引用暂不可用，原引用保留，请重新选择并验证。</p></section></template>
<template v-else><h2>核对最终配置并启动</h2><p class="create-hint">运行绑定配置、模型与模板的具体版本，操作完成后才显示成功。</p><div v-for="c in config.channels" :key="c.channel_id" class="create-source"><h3>{{c.name}}</h3><p>{{c.requirement_text||'原始需求为空'}}</p><dl class="detail-meta"><div><dt>监测条件</dt><dd>{{label(c.target)}} / {{label(c.rule)}} / {{c.duration_seconds==null?'时长未设':`${c.duration_seconds}秒`}}</dd></div><div><dt>视频数量</dt><dd>{{bindings(c).length}}</dd></div><div class="wide"><dt>模型 / 模板快照</dt><dd>{{c.capability_ref?`${c.capability_ref.model_id} @ ${c.capability_ref.model_version} / ${c.capability_ref.template_id} @ ${c.capability_ref.template_version}`:'未选择'}}</dd></div><div v-for="b in bindings(c)" :key="b.source_id" class="wide"><dt>{{sources.find(s=>s.id===b.source_id)?.name??b.source_id}}</dt><dd>{{b.regions?.length??0}} 个区域 · {{b.start_media_ms==null?'全段 / 直播':`${b.start_media_ms/1000}–${b.end_media_ms!/1000} 秒`}}</dd></div></dl></div></template>
</fieldset><section v-if="step>=2&&!operation" class="create-review"><NCheckbox v-model:checked="reviewed" :disabled="frozen">我已核对全部原文与结构化条件；未覆盖的条件需补充，不能静默忽略。</NCheckbox><NButton type="primary" secondary :loading="busy" :disabled="frozen||!reviewed||hasPending" @click="evaluate">保存并验证可执行性</NButton></section></section>
<aside class="panel create-summary"><span class="create-eyebrow">配置概览</span><h2>{{name||'未命名监测任务'}}</h2><div class="create-summary-numbers"><div><strong>{{config.channels?.length??0}}</strong><span>监测组</span></div><div><strong>{{(config.channels??[]).reduce((n,c)=>n+bindings(c).length,0)}}</strong><span>视频绑定</span></div></div><p>{{dirty?'有尚未保存的修改':agent?'服务端草稿已保存':'开始配置新任务'}}</p><p v-if="hasPending" class="notice">存在未完成的区域，请先闭合并保存。</p><div v-if="agent" class="create-ids"><span>agentId</span><code>{{agent.id}}</code><span>revisionId</span><code>{{revision?.id}}</code><RouterLink :to="`/agents/${agent.id}/config`">查看智能体配置</RouterLink></div>
<div class="create-assessment" aria-live="polite"><h3>可执行性评估</h3><p v-if="!validation">{{dirty?'配置已变化，需要重新验证。':'尚未验证当前配置。'}}</p><template v-else><strong>{{verdictLabel(validation.verdict)}}</strong><small v-if="validation.data_origin==='mock'">模拟结果</small><ul><li v-for="v in [...(validation.missing_conditions??[]),...(validation.unsupported_conditions??[]),...(validation.evidence_limitations??[])]" :key="v">{{v}}</li></ul><p>有效至 {{new Date(validation.expires_at).toLocaleTimeString()}}</p></template></div>
<template v-if="step===3&&!operation"><NCheckbox v-model:checked="confirmed" :disabled="!validEvaluation||frozen">我确认配置、源范围和能力限制，同意按上述版本启动。</NCheckbox><NButton block type="primary" :loading="busy" :disabled="!canStart" @click="start">确认并启动</NButton><p v-if="blockReason" class="create-hint">{{blockReason}}</p></template>
<div v-if="operation" class="create-assessment"><h3>{{statusLabel(operation.state)}}</h3><p>{{operation.message}}</p><code>{{operation.id}}</code><div v-for="c in operation.channels" :key="c.channel_id+':'+c.source_id" class="create-operation"><span>{{sources.find(s=>s.id===c.source_id)?.name??c.source_id}} · {{statusLabel(c.state)}}</span><p>{{c.message}}</p><code v-if="c.new_run_id">runId: {{c.new_run_id}}</code></div><NButton :disabled="busy" @click="poll">刷新操作状态</NButton><RouterLink v-if="agent" :to="`/agents/${agent.id}/live`">进入智能体详情</RouterLink></div><p v-if="revision?.state==='published'&&!operation" class="notice">配置已发布。可重试上一次启动请求，或到智能体详情核对状态。</p>
</aside></div><footer class="create-footer"><span>{{agent?'草稿已关联智能体':'保存后由智能体服务分配 ID'}}</span><div class="create-actions"><NButton :disabled="frozen||hasPending" :loading="busy" @click="saveDraft">保存草稿</NButton><NButton :disabled="busy||hasPending||step===0" @click="step--">上一步</NButton><NButton v-if="step<3" type="primary" :disabled="busy||hasPending" @click="step++">下一步</NButton><NButton v-if="agent" @click="router.push(`/agents/${agent.id}/config`)">查看已保存配置</NButton></div></footer>
</template>
